298	// Strict decoding of committed circuit records.
299	//
300	// A circuit record in data.json must name each of name, version, constraints,
301	// public_inputs, private_inputs, frozen and description exactly once, with
302	// the exact JSON type the writer emits (string / integer / integer / integer
303	// / integer / boolean / string). A missing key, a null, a wrong type or a
304	// repeated key is data corruption and refuses the whole directory read: a
305	// missing or null frozen flag must not silently read as false (turning a
306	// frozen version back into an editable draft), and a repeated key must not
307	// resolve to its last value. An explicit 0, false or "" is an ordinary value
308	// and stays legal. The definition member remains the one optional field: it
309	// may be absent or null (the legacy counts-only state); when present it goes
310	// through the strict persistDefinition decoder.
311	//
312	// Only shape is judged here. The domain rules (non-blank name, positive
313	// version and constraint count, non-negative input counts) keep being
314	// re-checked by validateEnvelope.
315	
316	var persistCircuitFields = []string{
317		"name", "version", "constraints", "public_inputs", "private_inputs",
318		"frozen", "description", "definition",
319	}
320	
321	// storedRecordShape is the shared strict-JSON rule set (definition_schema.go)
322	// tagged for committed data: every structural failure in a stored circuit
323	// record is data corruption, never a bad request.
324	var storedRecordShape = jsonShape{fail: corruptf}
325	
326	func (c *persistCircuit) UnmarshalJSON(raw []byte) error {
327		const what = "stored circuit record"
328		if string(bytes.TrimSpace(raw)) == "null" {
329			return corruptf("%s must be a JSON object, not null", what)
330		}
331		members, err := strictCircuitObject(raw, what)
332		if err != nil {
333			return err
334		}
335	
336		var out persistCircuit
337	
338		requireString := func(key string, dst *string) error {
339			r, err := storedRecordShape.require(members, key, what)
340			if err != nil {
341				return err
342			}
343			v, err := storedRecordShape.string(r, what+" field "+strconv.Quote(key))
344			if err != nil {
345				return err
346			}
347			*dst = v
348			return nil
349		}
350		requireInt := func(key string, dst *int) error {
351			r, err := storedRecordShape.require(members, key, what)
352			if err != nil {
353				return err
354			}
355			v, err := storedRecordShape.int(r, what+" field "+strconv.Quote(key))
356			if err != nil {
357				return err
358			}
359			*dst = v
360			return nil
361		}
362	
363		if err := requireString("name", &out.Name); err != nil {
364			return err
365		}
366		if err := requireInt("version", &out.Version); err != nil {
367			return err
368		}
369		if err := requireInt("constraints", &out.Constraints); err != nil {
370			return err
371		}
372		if err := requireInt("public_inputs", &out.PublicInputs); err != nil {
373			return err
374		}
375		if err := requireInt("private_inputs", &out.PrivateInputs); err != nil {
376			return err
377		}
378		frozenRaw, err := storedRecordShape.require(members, "frozen", what)
379		if err != nil {
380			return err
381		}
382		out.Frozen, err = storedRecordShape.bool(frozenRaw, what+" field "+strconv.Quote("frozen"))
383		if err != nil {
384			return err
385		}
386		if err := requireString("description", &out.Description); err != nil {
387			return err
388		}
389	
390		// definition is the only optional member: absent or null both mean the
391		// counts-only legacy state.
392		if defRaw, present := members["definition"]; present {
393			if string(bytes.TrimSpace(defRaw)) != "null" {
394				var def persistDefinition
395				if err := json.Unmarshal(defRaw, &def); err != nil {
396					var se StoreError
397					if errors.As(err, &se) {
398						return err // already reported as data corruption
399					}
400					return corruptf("%s field %s is not a valid constraint definition: %v", what, strconv.Quote("definition"), err)
401				}
402				out.Definition = &def
403			}
404		}
405	
406		*c = out
407		return nil
408	}
