755	func sortEnvelope(env *envelope) {
756		sort.Slice(env.Circuits, func(i, j int) bool {
757			if env.Circuits[i].Name != env.Circuits[j].Name {
758				return env.Circuits[i].Name < env.Circuits[j].Name
759			}
760			return env.Circuits[i].Version < env.Circuits[j].Version
761		})
762		sort.Slice(env.Setups, func(i, j int) bool {
763			if env.Setups[i].Name != env.Setups[j].Name {
764				return env.Setups[i].Name < env.Setups[j].Name
765			}
766			return env.Setups[i].Version < env.Setups[j].Version
767		})
768		sort.Slice(env.Jobs, func(i, j int) bool { return env.Jobs[i].ID < env.Jobs[j].ID })
769		sort.Slice(env.Artifacts, func(i, j int) bool {
770			if env.Artifacts[i].Name != env.Artifacts[j].Name {
771				return env.Artifacts[i].Name < env.Artifacts[j].Name
772			}
773			return env.Artifacts[i].Version < env.Artifacts[j].Version
774		})
775	}
776	
777	// validateEnvelope re-checks every invariant on load so a tampered or
778	// hand-edited file cannot bypass the domain rules.
779	func validateEnvelope(env envelope) error {
780		seenCircuit := make(map[[2]string]bool)
781		circuitOK := make(map[[2]string]bool)
782		for i, c := range env.Circuits {
783			key := [2]string{c.Name, itoa(c.Version)}
784			if c.Name == "" || strings.TrimSpace(c.Name) == "" {
785				return fmt.Errorf("circuit #%d has an empty or blank name", i+1)
786			}
787			if c.Version <= 0 {
788				return fmt.Errorf("circuit %q version %d is not a positive integer", c.Name, c.Version)
789			}
790			if seenCircuit[key] {
791				return fmt.Errorf("circuit %q version %d appears more than once", c.Name, c.Version)
792			}
793			seenCircuit[key] = true
794			if c.Constraints <= 0 {
795				return fmt.Errorf("circuit %q v%d: constraints must be > 0", c.Name, c.Version)
796			}
797			if c.PublicInputs < 0 || c.PrivateInputs < 0 {
798				return fmt.Errorf("circuit %q v%d: input counts must not be negative", c.Name, c.Version)
799			}
800			// The same representability rule the write path enforces: wire 0 plus
801			// every declared input must fit inside the platform's int. A record
802			// beyond that bound can never have been written by this build and
803			// cannot be checked safely, so the directory is corrupt rather than
804			// silently narrowed or read with a wrapped-around layout.
805			if !inputLayoutRepresentable(c.PublicInputs, c.PrivateInputs) {
806				return fmt.Errorf("circuit %q v%d: input layout is not representable: 1 constant wire + %d public + %d private inputs exceeds the platform limit of %d wires",
807					c.Name, c.Version, c.PublicInputs, c.PrivateInputs, maxInputWires)
808			}
809			if c.Definition != nil {
810				if err := validatePersistDefinition(c.Name, c.Version, c.Constraints, c.PublicInputs, c.PrivateInputs, c.Definition); err != nil {
811					return err
812				}
813			}
814			circuitOK[key] = true
815		}
816		seenSetup := make(map[[2]string]bool)
817		for i, p := range env.Setups {
818			key := [2]string{p.Name, itoa(p.Version)}
819			if !circuitOK[key] {
820				return fmt.Errorf("setup #%d belongs to unknown circuit %q v%d", i+1, p.Name, p.Version)
821			}
822			c := findPersistCircuit(env.Circuits, p.Name, p.Version)
823			if c == nil || !c.Frozen {
824				return fmt.Errorf("setup belongs to non-frozen circuit %q v%d", p.Name, p.Version)
825			}
826			if seenSetup[key] {
827				return fmt.Errorf("setup for %q v%d appears more than once", p.Name, p.Version)
828			}
829			seenSetup[key] = true
830		}
831		seenJob := make(map[string]bool)
832		for i, j := range env.Jobs {
833			if j.ID == "" || strings.TrimSpace(j.ID) == "" {
834				return fmt.Errorf("job #%d has an empty or blank id", i+1)
835			}
836			if seenJob[j.ID] {
837				return fmt.Errorf("job %q appears more than once", j.ID)
838			}
839			seenJob[j.ID] = true
840			if j.Kind != "prove" {
841				return fmt.Errorf("job %q has unsupported kind %q", j.ID, j.Kind)
842			}
843			if j.Attempt <= 0 {
844				return fmt.Errorf("job %q: attempt must be a positive integer", j.ID)
845			}
846			key := [2]string{j.Circuit, itoa(j.Version)}
847			if !circuitOK[key] {
848				return fmt.Errorf("job %q binds to unknown circuit %q v%d", j.ID, j.Circuit, j.Version)
849			}
850			c := findPersistCircuit(env.Circuits, j.Circuit, j.Version)
851			if c == nil || !c.Frozen {
852				return fmt.Errorf("job %q binds to non-frozen circuit %q v%d", j.ID, j.Circuit, j.Version)
853			}
854			if !seenSetup[key] {
855				return fmt.Errorf("job %q binds to circuit %q v%d without a trusted setup", j.ID, j.Circuit, j.Version)
856			}
857			// A recorded compiled-artifact binding must still resolve against the
858			// pinned version's artifact; a dangling or mismatched binding makes
859			// the file unreadable rather than silently dropping the binding.
860			if j.CompiledHash != "" {
861				artifact := findArtifact(env.Artifacts, j.Circuit, j.Version)
862				if artifact == nil {
863					return fmt.Errorf("job %q binds to compiled artifact of %q v%d which is missing", j.ID, j.Circuit, j.Version)
864				}
865				if artifact.Hash != j.CompiledHash {
866					return fmt.Errorf("job %q compiled hash %q does not match the artifact of %q v%d (hash %q)",
867						j.ID, j.CompiledHash, j.Circuit, j.Version, artifact.Hash)
868				}
869			}
870		}
871		seenArtifact := make(map[[2]string]bool)
872		for i, a := range env.Artifacts {
873			key := [2]string{a.Name, itoa(a.Version)}
874			if !circuitOK[key] {
875				return fmt.Errorf("artifact #%d belongs to unknown circuit %q v%d", i+1, a.Name, a.Version)
876			}
877			c := findPersistCircuit(env.Circuits, a.Name, a.Version)
878			if c == nil || !c.Frozen {
879				return fmt.Errorf("artifact belongs to non-frozen circuit %q v%d", a.Name, a.Version)
880			}
881			if seenArtifact[key] {
882				return fmt.Errorf("artifact for %q v%d appears more than once", a.Name, a.Version)
883			}
884			seenArtifact[key] = true
885			if c.Definition == nil {
886				return fmt.Errorf("artifact for %q v%d has no constraint definition", a.Name, a.Version)
887			}
888			if a.Constraints != c.Constraints {
889				return fmt.Errorf("artifact for %q v%d constraint count %d disagrees with the version's %d",
890					a.Name, a.Version, a.Constraints, c.Constraints)
891			}
892			def, err := definitionFromPersist(*c.Definition, c.PublicInputs, c.PrivateInputs)
893			if err != nil {
894				return fmt.Errorf("artifact for %q v%d cannot be checked against its definition: %w", a.Name, a.Version, err)
895			}
896			if int64(a.Modulus) != def.modulus || len(def.constraints) != a.Constraints {
897				return fmt.Errorf("artifact for %q v%d is inconsistent with its stored definition", a.Name, a.Version)
898			}
899			wantHash := artifactHash(a.Name, a.Version, def)
900			if a.Hash != wantHash {
901				return fmt.Errorf("artifact for %q v%d hash %q does not recompute from the definition (want %q)",
902					a.Name, a.Version, a.Hash, wantHash)
903			}
904		}
905		return nil
906	}
907	
908	// validatePersistDefinition re-validates a stored definition against its
909	// version's declared counts: prime modulus, in-range wires and an exact
910	// constraint count match.
911	func validatePersistDefinition(name string, version, constraints, public, private int, def *persistDefinition) error {
912		parsed, err := definitionFromPersist(*def, public, private)
913		if err != nil {
914			return fmt.Errorf("circuit %q v%d has a corrupt constraint definition: %w", name, version, err)
915		}
916		if !parsed.compatibleWith(constraints, public, private) {
917			return fmt.Errorf("circuit %q v%d definition is incompatible with its declared counts", name, version)
918		}
919		return nil
920	}
921	
922	func findPersistCircuit(cs []persistCircuit, name string, version int) *persistCircuit {
923		for i := range cs {
924			if cs[i].Name == name && cs[i].Version == version {
925				return &cs[i]
926			}
927		}
928		return nil
929	}
930	
931	func itoa(v int) string { return fmt.Sprintf("%d", v) }
932

