3	import (
4		"encoding/json"
5		"os"
6		"path/filepath"
7		"strings"
8		"testing"
9	)
10	
11	// These tests cover the CLI contract for a damaged compiled-artifact binding
12	// on a committed job record: a compiled_hash that is present but not a JSON
13	// string (null above all) is data corruption, not an unbound job. Every data
14	// command fails at open with exit code 3 (the existing read-failure code),
15	// prints no record, and leaves data.json byte-for-byte in place.
16	
17	// seedBoundJobCLI drives the CLI through a legal create + import + freeze +
18	// setup + compile + bound job-submit and returns the artifact hash.
19	func seedBoundJobCLI(t *testing.T, dir string) string {
20		t.Helper()
21		defPath := writeFile(t, filepath.Dir(dir), "def.json", cliCorruptDef)
22		must := func(what string, r cliResult) {
23			t.Helper()
24			if r.code != 0 {
25				t.Fatalf("%s: code=%d err=%s", what, r.code, r.err)
26			}
27		}
28		must("create", callCLI(t, "circuit-create", "--dir", dir, "--name", "mul", "--version", "1",
29			"--constraints", "1", "--public-inputs", "1", "--private-inputs", "1"))
30		must("import", callCLI(t, "constraint-import", "--dir", dir, "--name", "mul", "--version", "1",
31			"--file", defPath))
32		must("freeze", callCLI(t, "circuit-freeze", "--dir", dir, "--name", "mul", "--version", "1"))
33		must("setup", callCLI(t, "setup-record", "--dir", dir, "--name", "mul", "--version", "1"))
34		compiled := callCLI(t, "circuit-compile", "--dir", dir, "--name", "mul", "--version", "1")
35		must("compile", compiled)
36		hash := ""
37		for _, field := range strings.Fields(compiled.out) {
38			if strings.HasPrefix(field, "hash=") {
39				hash = strings.TrimPrefix(field, "hash=")
40			}
41		}
42		if hash == "" {
43			t.Fatalf("compile output carries no hash: %q", compiled.out)
44		}
45		must("submit", callCLI(t, "job-submit", "--dir", dir, "--id", "j1", "--name", "mul", "--version", "1",
46			"--hash", hash))
47		return hash
48	}
49	
50	// corruptBoundJobCLI rewrites the committed j1 binding field to the given
51	// raw JSON value and returns the damaged bytes now on disk.
52	func corruptBoundJobCLI(t *testing.T, dir, hash, replacement string) []byte {
53		t.Helper()
54		path := filepath.Join(dir, "data.json")
55		raw, err := os.ReadFile(path)
56		if err != nil {
57			t.Fatal(err)
58		}
59		field := `"compiled_hash": "` + hash + `"`
60		if !strings.Contains(string(raw), field) {
61			t.Fatalf("committed file does not carry the bound field %q", field)
62		}
63		bad := []byte(strings.Replace(string(raw), field, `"compiled_hash": `+replacement, 1))
64		if err := os.WriteFile(path, bad, 0o644); err != nil {
65			t.Fatal(err)
66		}
67		return bad
68	}
69	
70	// TestCLICorruptJobCompiledHashExitCode: a non-string compiled_hash makes
71	// reads, submissions and unrelated writes all exit 3 without touching the
72	// file, and the read-failure message names the damaged job.
73	func TestCLICorruptJobCompiledHashExitCode(t *testing.T) {
74		dir := filepath.Join(t.TempDir(), "bench")
75		hash := seedBoundJobCLI(t, dir)
76		bad := corruptBoundJobCLI(t, dir, hash, "null")
77	
78		commands := [][]string{
79			{"job-get", "--dir", dir, "--id", "j1"},
80			{"job-list", "--dir", dir},
81			{"job-submit", "--dir", dir, "--id", "j2", "--name", "mul", "--version", "1"},
82			{"circuit-list", "--dir", dir},
83			{"circuit-create", "--dir", dir, "--name", "other", "--version", "1"},
84		}
85		for _, args := range commands {
86			r := callCLI(t, args...)
87			if r.code != 3 {
88				t.Fatalf("%s: want exit 3, got %d (out=%q err=%q)", args[0], r.code, r.out, r.err)
89			}
90			if r.out != "" {
91				t.Fatalf("%s printed a record despite corruption: %q", args[0], r.out)
92			}
93			if !strings.Contains(r.err, "read failed") || !strings.Contains(r.err, "data corrupt") {
94				t.Fatalf("%s: unexpected error text %q", args[0], r.err)
95			}
96		}
97	
98		// The failure names the job whose binding field is damaged.
99		r := callCLI(t, "job-get", "--dir", dir, "--id", "j1")
100		if !strings.Contains(r.err, `"j1"`) || !strings.Contains(r.err, "compiled_hash") {
101			t.Fatalf("error does not name the damaged job and field: %q", r.err)
102		}
103	
104		left, err := os.ReadFile(filepath.Join(dir, "data.json"))
105		if err != nil {
106			t.Fatal(err)
107		}
108		if string(left) != string(bad) {
109			t.Fatalf("data.json changed after refused commands")
110		}
111	}
112	
113	// TestCLIJobCompiledHashShapes: the two legal expressions of the binding keep
114	// working at the CLI — an omitted field and an explicit empty string both
115	// read as unbound — while every other JSON type exits 3.
116	func TestCLIJobCompiledHashShapes(t *testing.T) {
117		t.Run("explicit empty string stays unbound", func(t *testing.T) {
118			dir := filepath.Join(t.TempDir(), "bench")
119			hash := seedBoundJobCLI(t, dir)
120			corruptBoundJobCLI(t, dir, hash, `""`)
121	
122			r := callCLI(t, "job-get", "--dir", dir, "--id", "j1")
123			if r.code != 0 {
124				t.Fatalf("explicit empty binding must load: code=%d err=%s", r.code, r.err)
125			}
126			if strings.Contains(r.out, "compiled_hash") {
127				t.Fatalf("explicit empty hash displayed as bound: %q", r.out)
128			}
129		})
130	
131		t.Run("non-string values are corrupt", func(t *testing.T) {
132			for _, value := range []string{"5", "true", `["x"]`, `{"h":"x"}`} {
133				dir := filepath.Join(t.TempDir(), "bench")
134				hash := seedBoundJobCLI(t, dir)
135				corruptBoundJobCLI(t, dir, hash, value)
136				r := callCLI(t, "job-list", "--dir", dir)
137				if r.code != 3 || !strings.Contains(r.err, "read failed") {
138					t.Fatalf("compiled_hash=%s: want exit 3 read failure, got code=%d err=%q", value, r.code, r.err)
139				}
140			}
141		})
142	}
143	
144	// TestCLIJobCompiledHashDuplicateExitCode: a repeated compiled_hash key —
145	// including one repeated through a JSON escape spelling — exits 3.
146	func TestCLIJobCompiledHashDuplicateExitCode(t *testing.T) {
147		dir := filepath.Join(t.TempDir(), "bench")
148		hash := seedBoundJobCLI(t, dir)
149		path := filepath.Join(dir, "data.json")
150		raw, err := os.ReadFile(path)
151		if err != nil {
152			t.Fatal(err)
153		}
154		field := `"compiled_hash": "` + hash + `"`
155		duplicate := field + `, "compiled\u005fhash": "` + hash + `"`
156		bad := []byte(strings.Replace(string(raw), field, duplicate, 1))
157		// Sanity: the damaged file really does name the key twice after JSON
158		// unescaping, so the test exercises the duplicate path.
159		var probe struct {
160			Jobs []map[string]json.RawMessage `json:"jobs"`
161		}
162		if err := json.Unmarshal(bad, &probe); err != nil || len(probe.Jobs) != 1 {
163			t.Fatalf("damaged file does not decode: %v", err)
164		}
165		if _, ok := probe.Jobs[0]["compiled_hash"]; !ok {
166			t.Fatalf("escaped duplicate key did not decode to compiled_hash")
167		}
168		if err := os.WriteFile(path, bad, 0o644); err != nil {
169			t.Fatal(err)
170		}
171	
172		r := callCLI(t, "job-list", "--dir", dir)
173		if r.code != 3 || !strings.Contains(r.err, "read failed") || !strings.Contains(r.err, "compiled_hash") {
174			t.Fatalf("duplicate compiled_hash: want exit 3 read failure naming the field, got code=%d err=%q", r.code, r.err)
175		}
176		left, err := os.ReadFile(path)
177		if err != nil {
178			t.Fatal(err)
179		}
180		if string(left) != string(bad) {
181			t.Fatalf("data.json changed after refused command")
182		}
183	}
