		{"null plus value", `"Compiled_Hash": null, "compiled_hash": "` + h + `"`},
		{"escaped uppercase", `"compiled_hash": "` + h + `", "COMPILED_HASH": "` + h + `"`},
	} {
		dir3, h3 := seedBoundJobStore(t)
		valid3, _ := readDataFile(t, dir3)
		r := strings.Replace(repl.r, h, h3, -1)
		bad3 := strings.Replace(string(valid3), `"compiled_hash": "`+h3+`"`, r, 1)
		writeDataFile(t, dir3, []byte(bad3))
		_, err := Open(dir3)
		if !errors.Is(err, ErrDataCorrupt) {
			t.Fatalf("%s: want ErrDataCorrupt, got %v", repl.name, err)
		}
		if !strings.Contains(err.Error(), "compiled_hash") {
			t.Fatalf("%s: error names field: %v", repl.name, err)
		}
		got3, _ := readDataFile(t, dir3)
		if string(got3) != bad3 {
			t.Fatalf("%s: file modified", repl.name)
		}
	}

	// 4. Non-string values under a case variant are corruption.
	for _, v := range []string{"5", "true", `["x"]`, `{"h":"x"}`} {
		dir4, h4 := seedBoundJobStore(t)
		valid4, _ := readDataFile(t, dir4)
		bad4 := strings.Replace(string(valid4), `"compiled_hash": "`+h4+`"`, `"COMPILED_HASH": `+v, 1)
		writeDataFile(t, dir4, []byte(bad4))
		if _, err := Open(dir4); !errors.Is(err, ErrDataCorrupt) {
			t.Fatalf("COMPILED_HASH=%s: want ErrDataCorrupt, got %v", v, err)
		}
	}

	// 5. Case-variant explicit empty string stays unbound.
	dir5, h5 := seedBoundJobStore(t)
	valid5, _ := readDataFile(t, dir5)
	empty := strings.Replace(string(valid5), `"compiled_hash": "`+h5+`"`, `"COMPILED_HASH": ""`, 1)
	writeDataFile(t, dir5, []byte(empty))
	s5, err := Open(dir5)
	if err != nil {
		t.Fatalf("case-variant empty binding must load: %v", err)
	}
	j5, _ := s5.GetJob("j-bound")
	if j5.CompiledHash != "" {
		t.Fatalf("empty case-variant binding read as bound: %+v", j5)
	}
	s5.Close()
}

